public final class Ipv4Packet{private final int headerLength;private final int totalLength;private final int protocol;private final IpAddress source;private final IpAddress destination;private final byte[] payload;private final int ttl;private final int flagsFragment;public Ipv4Packet(int headerLength,int totalLength,int protocol,IpAddress source,IpAddress destination,byte[] payload,int ttl,int flagsFragment){this.headerLength=headerLength;this.totalLength=totalLength;this.protocol=protocol;this.source=source;this.destination=destination;this.payload=payload==null?new byte[0]:payload;this.ttl=ttl;this.flagsFragment=flagsFragment;}public static ParseResult<Ipv4Packet> parse(byte[] data){Diagnostics d=new Diagnostics();if(data==null||data.length<20)return ParseResult.failure("ipv4.truncated","IPv4 header truncated");int first=data[0]&255;int version=first>>>4;int ihl=(first&15)*4;if(version!=4)d.high("ipv4.version","not an IPv4 packet");if(ihl<20||ihl>data.length)return ParseResult.failure("ipv4.ihl","invalid IPv4 header length");int total=Endian.u16be(data,2);if(total<ihl){d.high("ipv4.total_length","total length shorter than header");total=data.length;}if(total>data.length){d.medium("ipv4.truncated_payload","total length exceeds captured bytes");total=data.length;}int checksum=Endian.u16be(data,10);byte[] header=SafeSlice.copy(data,0,ihl);header[10]=0;header[11]=0;int calc=Checksums.internetChecksum(header);if(checksum!=0&&calc!=checksum)d.low("ipv4.checksum","header checksum mismatch");int proto=data[9]&255;IpAddress src=IpAddress.fromBytes(data,12);IpAddress dst=IpAddress.fromBytes(data,16);byte[] payload=SafeSlice.copy(data,ihl,total-ihl);return ParseResult.of(new Ipv4Packet(ihl,total,proto,src,dst,payload,data[8]&255,Endian.u16be(data,6)),d);}public int headerLength(){return headerLength;}public int totalLength(){return totalLength;}public int protocol(){return protocol;}public IpAddress source(){return source;}public IpAddress destination(){return destination;}public byte[] payload(){return payload;}public int ttl(){return ttl;}public boolean fragmented(){return(flagsFragment&0x3fff)!=0;}public String protocolName(){return SecurityCatalog.ipProtocolName(protocol);}}
